    for i in range(1):
        file_input = open(f"GreedyMotifSearchPseudocounts/inputs/input_{i + 1}.txt")
        text = file_input.read().strip()
        k, t, Dna = parsing(text)
        file_output = open(f"GreedyMotifSearchPseudocounts/outputs/output_{i + 1}.txt")
        file_output_text = file_output.read().strip()
        file_output_dna = file_output_text.strip().split()

        result = GreedyMotifSearchPseudocounts(Dna, k, t)

